(
    defaultPrim = "Asset"
)

def "Asset"
{
    int c.connect = </Asset/Part.b[/Asset].d>
    rel r = [
        </Asset.b[/Asset/Part].d>,
        </Asset/Part.b[/Asset].d>,
        </Asset/Part.x.mapper[/Asset/Part.y]>,
    ]

    def "Part"
    {
        int x = 1
        int y = 1
    }
}

layers.scene.usda:
#usda 1.0
(
    subLayers = [
        @sub.usda@
    ]
)

def "World"
{
    def "A"
    {
        rel b = </World/C>
        int x = 1

        def "Kid"
        {
            rel b = </World/C>
        }
    }

    def "C"
    {
        rel b = </World/A>
        int y = 1
    }

    def "Group"
    {
    }

    def "User"
    {
        rel across
        rel across.default = </World/C.b[/World/A/Kid].d>        
        rel after = [
            </World/A.b[/World/C].x>,
            </World/C.b[/World/A].y>,
        ]
        rel before = [
            </World/A.b[/World/C].d>,
            </World/A/Kid.b[/World/C].d>,
            </World/A.x.mapper[/World/C.y]>,
        ]
        rel both = [
            </World/A.b[/World/A/Kid].d>,
            </World/A.x.mapper[/World/A.x]>,
        ]
        int conn.connect = [
            </World/A.b[/World/C].d>,
            </World/C.b[/World/A].d>,
            </World/A/Kid.b[/World/C].d>,
        ]
        rel dependent = [
            </World/A/Kid>,
            </World/C.y>,
            </World/A.x>,
        ]
        rel dependent.default = </World/C.b[/World/A/Kid].d>        
        delete rel edits = </World/C.b[/World/A].d>
        prepend rel edits = [
            </World/A.b[/World/C].d>,
            </World/C.b[/World/A].d>,
        ]
        append rel edits = </World/A.x.mapper[/World/C.y]>
        reorder rel edits = [
            </World/C.b[/World/A].d>,
            </World/A.b[/World/C].d>,
        ]
        pathExpression expr = "/World/A/Kid /World/C.y /World/A.x"
        rel independent = </World/Group>
        rel independent.default = </World/C.b[/World/A/Kid].d>        
        rel inside = [
            </World/C.b[/World/A].d>,
            </World/C.b[/World/A/Kid].d>,
            </World/C.y.mapper[/World/A.x]>,
            </World/C.b[/World/C.b[/World/A].d].e>,
        ]
        delete int listed.connect = </World/A/Kid.b[/World/C].d>
        prepend int listed.connect = </World/A.b[/World/A/Kid].d>
        append int listed.connect = </World/C.b[/World/A].d>
        rel relative = </World/A.b[../C].d>
    }

    def "Lone"
    {
        rel only
        rel only.default = </World/C.b[/World/A/Kid].d>        
    }

    def "V" (
        variants = {
            string s = "on"
        }
        prepend variantSets = "s"
    )
    {
        variantSet "s" = {
            "off" {
                int c.connect = </World/A.b[/World/C].d>
                rel r = [
                    </World/A.b[/World/C].d>,
                    </World/C.b[/World/A].d>,
                    </World/A/Kid>,
                ]

            }
            "on" {
                int c.connect = </World/A.b[/World/C].d>
                rel r = [
                    </World/A.b[/World/C].d>,
                    </World/C.b[/World/A].d>,
                    </World/A/Kid>,
                ]

            }
        }
    }

    def "R" (
        prepend references = @asset.usda@</Asset>
    )
    {
        rel toR = [
            </World/R.b[/World/R/Part].d>,
            </World/R/Part.x.mapper[/World/A.x]>,
        ]
    }
}

